ST.xhtml:p:
RTrigger1(CLK := g_biLoadAbsOpen);
RTrigger2(CLK := g_biLoadAbsClose);
RTrigger3(CLK := g_biClearError);
RTrigger4(CLK := g_biCutCheck);
RTrigger5(CLK := g_biManualLoad);

IF RTrigger1.Q THEN
  nLoadAbsState := 1;
  g_boLoadAbsDone := FALSE;
  g_boLoadTailDone := FALSE;
  g_boIgnoreCut := FALSE;
END_IF;
IF RTrigger2.Q THEN
  g_boLoadAbsDone := FALSE;
  g_boLoadTailDone := FALSE;
END_IF;
g_foLoadAbsTest := g_fOvershootDistance;

CASE nLoadAbsState OF
  0:
    nLoadAbsState := 0;
  1:
    IF bDryRunEnable OR LREAL_TO_DINT(g_fiLoadAbsType) = 6 OR LREAL_TO_DINT(g_fiLoadAbsType) = 3 OR (NOT bLoadBlankingEnable) THEN
      nLoadAbsState := 2;
    ELSE
      IF g_bLengthCheck5 THEN
        g_bLoadAbsWarn := TRUE;
        nLoadAbsState := 21;
      ELSE
        nLoadAbsState := 2;
      END_IF;     
    END_IF;
  2:
    IF LREAL_TO_DINT(g_fiLoadAbsType) = 0 THEN
      dTargetPos := Axis_Load.NCTOPLC.SETPOS + g_fPartLenght - g_dOffset + 5.0 + g_dSlitLength;     
      g_LoadAbs.Velocity := dTargetVel;
      IF dTargetPos > g_dLoadMaxLimit THEN
        g_boIgnoreCut := TRUE;
        g_boLoadAbsDone := TRUE;
      END_IF;
    ELSIF LREAL_TO_DINT(g_fiLoadAbsType) = 1 THEN
      dTargetPos := Axis_Load.NCTOPLC.SETPOS + g_fPipeHead + dLsZDistance - g_fOvershootDistance;
      g_LoadAbs.Velocity := dTailVel;
    ELSIF LREAL_TO_DINT(g_fiLoadAbsType) = 2 THEN
      dTargetPos := g_dLoadMaxLimit;
      g_LoadAbs.Velocity := dTargetVel;
      dMaxLimitError := g_dLoadMaxLimit - Axis_Load.NCTOPLC.SETPOS - 5.0;
    ELSIF LREAL_TO_DINT(g_fiLoadAbsType) = 3 THEN
      dTargetPos := Axis_Load.NCTOPLC.SETPOS + g_fPartLenght - dMaxLimitError + 1.0 + g_dLoadMaxLimit - g_dTotalLength - g_fOvershootDistance + g_dSlitLength;
      g_foLoadAbsTest0 := dTargetPos;
      g_LoadAbs.Velocity := dTargetVel;
    ELSIF LREAL_TO_DINT(g_fiLoadAbsType) = 4 THEN
      dTargetPos := g_dTotalLength + dLsZDistance + g_fPartLenght - g_dPipeLength;
      g_LoadAbs.Velocity := dTailVel;
    ELSIF LREAL_TO_DINT(g_fiLoadAbsType) = 5 THEN
      dTargetPos := g_dTotalLength + dLsZDistance + g_fPipeHead - g_dPipeLength;
      g_LoadAbs.Velocity := dTailVel;
    ELSIF LREAL_TO_DINT(g_fiLoadAbsType) = 6 THEN
      dTargetPos := Axis_Load.NCTOPLC.SETPOS - 5.0;
      g_LoadAbs.Velocity := dTargetVel;
    ELSIF LREAL_TO_DINT(g_fiLoadAbsType) = 7 THEN
      dTargetPos := dManualLoadPos;
      g_LoadAbs.Velocity := dTargetVel;
    ELSIF LREAL_TO_DINT(g_fiLoadAbsType) = 8 THEN
      dTargetPos := Axis_Load.NCTOPLC.SETPOS + g_fPartLenght + dLsZDistance - g_fOvershootDistance;
      g_LoadAbs.Velocity := dTargetVel;
    ELSE
      dTargetPos := Axis_Load.NCTOPLC.SETPOS;
    END_IF;   
    IF g_boLoadAbsDone THEN
      nLoadAbsState := 0;
    ELSE
      nLoadAbsState := 3;
    END_IF;
  3:
    g_LoadAbs.Execute := TRUE;
    g_LoadAbs.Position := dTargetPos;
    IF g_LoadAbs.Done THEN
      g_LoadAbs.Execute := FALSE;
      g_boLoadAbsDone := TRUE;
      nLoadAbsState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nLoadAbsState := 20;
      nPauseState := 3;
    END_IF;
    IF g_LoadAbs.CommandAborted OR g_LoadAbs.Error THEN
      g_LoadAbs.Execute := FALSE;
      g_boLoadAbsDone := FALSE;
      nLoadAbsState := 0;
    END_IF;
  20:
    g_LoadAbs.Execute := FALSE;
    g_LoadStop.Execute := TRUE;
    IF g_LoadStop.Done AND g_bPlcStartBuffer THEN
      g_LoadStop.Execute := FALSE;
      nLoadAbsState := nPauseState;
    END_IF;
    IF g_LoadStop.CommandAborted OR g_LoadStop.Error THEN
      g_LoadStop.Execute := FALSE;
      nLoadAbsState := 0;
    END_IF;
  21:
    IF g_bLengthCheck5 THEN
      g_bLoadAbsWarn := TRUE;
    ELSE
      IF g_bPlcStartBuffer THEN
        nLoadAbsState := 1;
      END_IF;
    END_IF;
END_CASE;

IF RTrigger4.Q THEN
  IF bLoadBlankingEnable AND (NOT bDryRunEnable) THEN
    nCutCheckState := 1;
    g_boCutCheckDone := FALSE;
  ELSE
    g_boCutCheckDone := TRUE;
  END_IF;
END_IF;

CASE nCutCheckState OF
  0:
    IF (NOT bLoadBlankingEnable) OR bDryRunEnable THEN
      g_boCutCheckDone := TRUE;
    ELSE
      IF NOT g_bLengthCheck5 THEN
        g_boCutCheckDone := FALSE;
      END_IF; 
    END_IF;
  1:
    IF g_bLengthCheck5 THEN
      g_boCutCheckDone := TRUE;
      nCutCheckState := 0;
    ELSE
      g_bZFollowWarn := TRUE;
      nCutCheckState := 2;
    END_IF;
  2:
    IF g_bLengthCheck5 THEN
      IF g_bPlcStartBuffer THEN
        nCutCheckState := 1;
      END_IF;
    ELSE
      g_bZFollowWarn := TRUE;
    END_IF;
END_CASE;

IF RTrigger5.Q THEN
  nManualLoadState := 1;
  g_boManualLoadDone := FALSE;
END_IF;

CASE nManualLoadState OF
  0:
    nManualLoadState := 0;
  1:
    g_bManualLoadTip := TRUE;
    nManualLoadState := 2;
  2:
    IF g_bPlcStartBuffer THEN
      g_boManualLoadDone := TRUE;
      nManualLoadState := 3;
    END_IF;
  3:
    Ton_ManualLoad(IN := TRUE,PT := T#1000ms);
    IF Ton_ManualLoad.Q THEN
      g_boManualLoadDone := FALSE;
      nManualLoadState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nLoadAbsState := 0;
  nCutCheckState := 0;
  nManualLoadState := 0;
  Ton_ManualLoad(IN := FALSE);
  g_LoadAbs.Execute := FALSE;
  g_LoadStop.Execute := FALSE;
  g_boCutCheckDone := FALSE;
  g_boManualLoadDone := FALSE;
  g_boIgnoreCut := FALSE;
END_IF;
